var terrain=Terrain.activeTerrain;var bank=GameObject.Find("Fitted earth shoulders - existing elevated approaches only").GetComponent<MeshCollider>();var bridge=GameObject.Find("Bridge_ContinuousWalkDeck").GetComponent<MeshCollider>();var ground=terrain.GetComponent<TerrainCollider>();var report=new List<object>();foreach(var f in GameObject.Find("02 Main road bridge and footpaths").GetComponentsInChildren<MeshFilter>()){if(!(f.name.StartsWith("Path_")||f.name.StartsWith("MainRoad_")))continue;var col=f.GetComponent<MeshCollider>();var v=f.sharedMesh.vertices;int unsupported=0,samples=0;float minUp=1,maxAbove=0,maxStep=0;foreach(float lane in new[]{.15f,.325f,.5f,.675f,.85f}){float prev=0;bool first=true;for(int i=0;i<v.Length;i+=2){var p=f.transform.TransformPoint(Vector3.Lerp(v[i],v[i+1],lane));var ray=new Ray(p+Vector3.up*3,Vector3.down);float best=-999;Vector3 normal=Vector3.up;foreach(var c in new Collider[]{col,bridge,ground,bank}){RaycastHit hit;if(c.Raycast(ray,out hit,7)&&hit.point.y>best){best=hit.point.y;normal=hit.normal;}}samples++;if(best< -900){unsupported++;continue;}maxAbove=Mathf.Max(maxAbove,best-terrain.SampleHeight(p)-terrain.transform.position.y);minUp=Mathf.Min(minUp,normal.y);if(!first)maxStep=Mathf.Max(maxStep,Mathf.Abs(best-prev));first=false;prev=best;}}report.Add(new{name=f.name,samples,unsupported,maxHeightChangeBetweenRows=maxStep,minimumUpNormal=minUp,maxAboveTerrain=maxAbove});}var result=new{method="Vertical support sampled at every original cross-section on five lanes. Existing road/deck/terrain plus only the fitted approach shoulder collider. Height change includes ordinary continuous hills, not an inferred discrete step.",routes=report,totalSamples=report.Sum(o=>(int)o.GetType().GetProperty("samples").GetValue(o)),unsupported=report.Sum(o=>(int)o.GetType().GetProperty("unsupported").GetValue(o))};System.IO.File.WriteAllText("ArtSource/Pipeline/Review/BriarwickEnvironment07/SurfaceContinuity.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return new{result.totalSamples,result.unsupported};
